python3 -c "import requests;
for cell in ['K562', 'GM12878', 'HUVEC', 'HeLa-S3']:
    for name in ['enhancers', 'promoters']:
        url = f'https://raw.githubusercontent.com/HaoWuLab-Bioinformatics/Enhancer-MDLF/main/EPdata/{cell}/{name}.fasta'
        text = requests.get(url).text
        lines = text.splitlines()
        seqs = [l.strip().upper() for l in lines if l and not l.startswith('>')]
        seqs_ge_200 = [s for s in seqs if len(s) >= 200]
        print(f'{cell} {name}: total={len(seqs)}, >=200bp={len(seqs_ge_200)}')
"

