python3 -c "
import random
from collections import defaultdict

def dinucleotide_shuffle(s):
    for _ in range(50):
        if len(s) < 2:
            return s
        edges = defaultdict(list)
        for i in range(len(s) - 1):
            edges[s[i]].append(s[i+1])

        last_char = s[-1]
        res_edges = defaultdict(list)
        exit_edges = {}

        for u, v_list in list(edges.items()):
            v_list = list(v_list)
            random.shuffle(v_list)
            if u != last_char:
                if len(v_list) > 0:
                    exit_edges[u] = v_list.pop()
                    res_edges[u] = v_list
            else:
                res_edges[u] = v_list

        curr = s[0]
        result = [curr]

        while True:
            if res_edges[curr]:
                curr = res_edges[curr].pop()
            elif curr in exit_edges:
                curr = exit_edges.pop(curr)
            else:
                break
            result.append(curr)

        if len(result) == len(s):
            return ''.join(result)

    l = list(s)
    random.shuffle(l)
    return ''.join(l)

seq = 'ACATGATGACCCG'
print('Original:', seq)
for i in range(5):
    print(f'Shuffle {i}:', dinucleotide_shuffle(seq))
"

